/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// TAMRebatePostDateTransactionFinancial extension to handles posting of lines, amounts and tax information
/// </summary>
[ExtensionOf(classStr(TAMRebatePostDateTransactionFinancial))]
final class METTAMRebatePostDateTransactionFinancial_Extension
{
    private NoYesId metFollowTransItemGSTGroup;
    private ModuleInventCustVend rebateModule;

}

Method.Source:
/// CB201_RebatesExtension_GSTchanges
/// <summary>
/// Get posting amoutn query
/// </summary>
/// <param name = "_rebateDateTrans">TAMRebateDateTrans</param>
/// <returns>query</returns>
protected Query getPostingAmountQuery(TAMRebateDateTrans _rebateDateTrans)
{
    Query postingAmountQuery;

    postingAmountQuery = next getPostingAmountQuery(_rebateDateTrans);

    rebateModule = TAMRebateDeal::find(_rebateDateTrans.RebateDeal).ModuleInventCustVend;

    if (_rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate
    && (rebateModule == ModuleInventCustVend::Cust
        // CB705_VendorRebate add GST customisation for Vendor rebate too
    ||  rebateModule == ModuleInventCustVend::Vend))
    {
        metFollowTransItemGSTGroup = createDocument.getRebatePosting().METFollowTransItemGSTGroup;


        if (rebateParameters.METProcessByCustRebateInvByItemType == NoYes::Yes || metFollowTransItemGSTGroup)
        {
            createDocument.parmRebateDateTrans(_rebateDateTrans);

            QueryBuildDataSource rebateTransDataSource = postingAmountQuery.dataSourceTable(tableNum(TAMRebateTrans));

            if (metFollowTransItemGSTGroup)
            {
                rebateTransDataSource.addGroupByAndSelectionField(fieldNum(TAMRebateTrans, METItemTypeDescription));
                rebateTransDataSource.addGroupByAndSelectionField(fieldNum(TAMRebateTrans, METTaxItemGroup));
            }

            //Task182820-CB272_SalesInvoicing-rebates-start
            if (rebateParameters.METProcessByCustRebateInvByItemType)
            {
                rebateTransDataSource.addGroupByAndSelectionField(fieldNum(TAMRebateTrans, METItemTypes));
            }
            //Task182820-CB272_SalesInvoicing-rebates-end
        }
    }

    return postingAmountQuery;
}

/// CB201_RebatesExtension_GSTchanges
/// <summary>
/// Get posting amount key for rebate trans 
/// </summary>
/// <param name = "_rebateTrans">TAMRebateTrans</param>
/// <returns>container</returns>
protected container getPostingAmountMapKeyForRebateTrans(TAMRebateTrans _rebateTrans)
{
    container key = next getPostingAmountMapKeyForRebateTrans(_rebateTrans);
    TAMRebateDateTrans rebateDateTrans = createDocument.parmRebateDateTrans();

    if (rebateDateTrans.RebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        //Task182820-CB272_SalesInvoicing-rebates-start
        if (metFollowTransItemGSTGroup)
        {
            key += _rebateTrans.METTaxItemGroup;
        }

        if (rebateParameters.METProcessByCustRebateInvByItemType)
        {
            key += _rebateTrans.METItemTypeDescription;
        }
        //Task182820-CB272_SalesInvoicing-rebates-end
    }

    return key;
}

/// CB201_RebatesExtension_GSTchanges
/// <summary>
/// Create line for document
/// </summary>
/// <param name = "_postingAmount">Posting amount based on query</param>
/// <param name = "_postingAmountMapKey">Posting amount container key</param>
protected void createLineForDocument(Amount _postingAmount, container _postingAmountMapKey)
{
    if (conLen(_postingAmountMapKey) > 0)
    {
        //Task182820-CB272_SalesInvoicing-rebates-start
        if (metFollowTransItemGSTGroup)
        {
            TaxItemGroup itemSalesTaxGroup = conPeek(_postingAmountMapKey, 3);
            createDocument.parmItemSalesTaxGroup(itemSalesTaxGroup);
        }

        if (rebateParameters.METProcessByCustRebateInvByItemType)
        {
            Description itemTypeDescription;

            if (metFollowTransItemGSTGroup)
            {
                itemTypeDescription = conPeek(_postingAmountMapKey, 4);
            }
            else
            {
                itemTypeDescription = conPeek(_postingAmountMapKey, 3);
            }

            createDocument.parmItemTypeDescription(itemTypeDescription);
        }
        //Task182820-CB272_SalesInvoicing-rebates-end

    }

    next createLineForDocument(_postingAmount, _postingAmountMapKey);
}

/// <summary>
/// CB705_VendorRebatePosting
/// </summary>
/// <param name = "_rebateDateTrans"><c>TAMRebateDateTrans</c> record</param>
/// <returns><c>Common</c></returns>
protected Common processRebateDateTransaction(TAMRebateDateTrans _rebateDateTrans)
{
    // Make sure the createDocument.LedgerJournalTable is reset everytime processing a new TAMRebateDateTrans as
    // they are grouped by rebate type to make sure a new vendor invoice journal header is created.
    if (rebateParameters.METProcessVendRebateBasedVendRebType
    &&  this.METParmRebateTransactionType() == TAMRebateTransactionType::Rebate
    &&  rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend
    &&  rebateDeal.RebateType == TAMRebateType::Rebate
    &&  rebateDeal.RebateReconciliation == TAMRebateReconciliation::Deal
    &&  rebateDeal.METInvoiceConsolidationByRebateType == NoYes::Yes)
    {
        TAMRebateCreateDocumentFinancialLedgerJournal createDocumentJournalLocal;
        createDocumentJournalLocal = createDocument as TAMRebateCreateDocumentFinancialLedgerJournal;
        createDocumentJournalLocal.METResetLedgerJournalTable();
    }

    return next processRebateDateTransaction(_rebateDateTrans);
}
